fn p3d_print_f64(value: f64, decimals: i64) with IO, Mut, Panic, Div {
    if value < 0.0 {
        print("-")
    }
    let abs_val = if value < 0.0 { 0.0 - value } else { value }
    let int_part = abs_val as i64
    p3d_print_int(int_part)
    if decimals > 0 {
        print(".")
        var frac = abs_val - int_part as f64
        var d: i64 = 0
        while d < decimals {
            frac = frac * 10.0
            let digit = frac as i64
            p3d_print_int(digit)
            frac = frac - digit as f64
            d = d + 1
        }
    }
}

